  /* =================== BANCO DE PREGUNTAS =================== */
  const gen = {
    m5vernier: rnd => { const r2 = rnd() < 0.35, res = r2 ? 0.02 : 0.05, nmax = r2 ? 49 : 19, M = pick(rnd, [6, 8, 12, 15, 19, 22, 23, 27, 31, 36, 42, 48]), n = 1 + Math.floor(rnd() * nmax), v = M + n * res, MM = x => f(x, 2) + ' mm';
      return { q: 'En un vernier de ' + f(res, 2) + ' mm, el cero del nonio queda justo después de la marca de ' + M + ' mm de la regla y la línea ' + n + ' del nonio coincide con una de la regla. ¿Cuál es la medida?', op: ops(MM(v), [MM(M + n / 100), MM(M + n / 10), MM(M + n * (r2 ? 0.05 : 0.02))], [MM(M + 1 + n * res), MM(v + 0.5), MM(M + n)]), r: M + ' mm + ' + n + ' × ' + f(res, 2) + ' mm = ' + MM(v) + '.' }; },
    m5micro: rnd => { const S = pick(rnd, [5, 7, 8, 10, 12, 14, 16, 19, 21, 24]), half = rnd() < 0.5, T = 1 + Math.floor(rnd() * 49), v = S + (half ? 0.5 : 0) + T / 100, MM = x => f(x, 2) + ' mm';
      return { q: 'En un micrómetro de 0.01 mm, el cilindro muestra ' + S + ' mm ' + (half ? 'y se ve la marca del medio milímetro' : 'y todavía no se ve la marca del medio milímetro') + '; el tambor marca ' + T + '. ¿Cuál es la medida?', op: ops(MM(v), [MM(half ? v - 0.5 : v + 0.5), MM(S + T / 10), MM(S + T)], [MM(S + T / 1000), MM(v + 0.01), MM(v + 1)]), r: S + ' mm' + (half ? ' + 0.5 mm' : '') + ' + ' + T + ' × 0.01 mm = ' + MM(v) + '.' }; },
    m5rodamiento: rnd => { const sr = pick(rnd, ['60', '62', '63']), xx = pick(rnd, ['00', '01', '02', '03', '04', '05', '06', '07', '08', '10', '12']), k = +xx, b = k < 4 ? [10, 12, 15, 17][k] : k * 5, suf = pick(rnd, ['', '-2RS', '-ZZ']), MM = x => x + ' mm';
      return { q: '¿Qué diámetro interior tiene un rodamiento ' + sr + xx + suf + '?', op: ops(MM(b), k < 4 ? [MM(b - 2), MM(b + 5), MM(k * 5 || 5)] : [MM(k * 5 + 5), MM(k), MM(k * 10)], [MM(+sr), MM(b + 3), MM(b + 10)]), r: (k < 4 ? 'Las terminaciones 00 a 03 son fijas: ' + xx + ' = ' + b + ' mm.' : xx + ' × 5 = ' + b + ' mm.') + ' La serie (' + sr + ') cambia el ancho y el diámetro exterior, no el interior.' }; },
    m5mtbf: rnd => { const n = pick(rnd, [2, 3, 4, 5, 6, 8]), T = n * pick(rnd, [12, 15, 18, 20, 24, 30, 40]), R = pick(rnd, [1, 2, 3, 4, 6, 8, 10]), H = x => f(x, 2) + ' h', P = x => f(x, 1) + ' %', v = rnd();
      const base = 'En un mes, una estación operó ' + T + ' h y tuvo ' + n + ' fallas; repararlas tomó ' + R + ' h en total. ';
      if (v < 0.34) return { q: base + '¿Cuál es su MTBF?', op: ops(H(T / n), [H(R / n), H(n / T), H((T + R) / n)], [H(T / R), H(T * n)]), r: 'MTBF = tiempo de operación / fallas = ' + T + ' / ' + n + ' = ' + H(T / n) + '.' };
      if (v < 0.67) return { q: base + '¿Cuál es su MTTR?', op: ops(H(R / n), [H(T / n), H(n / R), H(R)], [H(R / T), H(R * n), H(R / n + 1)]), r: 'MTTR = tiempo de reparación / reparaciones = ' + R + ' / ' + n + ' = ' + H(R / n) + '.' };
      const D = T / (T + R) * 100;
      return { q: base + '¿Cuál es su disponibilidad?', op: ops(P(D), [P(R / T * 100), P(100 - R / T * 100), P(R / (T + R) * 100)], [P(D - 5), P(100 * n / (n + R)), P(D - 10)]), r: 'MTBF = ' + f(T / n, 2) + ' h y MTTR = ' + f(R / n, 2) + ' h; disponibilidad = MTBF / (MTBF + MTTR) = ' + T + ' / (' + T + ' + ' + R + ') = ' + P(D) + '.' }; },
    m5oee: rnd => { const P = x => f(x, 1) + ' %';
      if (rnd() < 0.6) { const A = pick(rnd, [80, 85, 88, 90, 92, 95]), Rn = pick(rnd, [75, 80, 85, 90, 95]), Q = pick(rnd, [90, 95, 97, 98, 99]), o = A * Rn * Q / 10000;
        return { q: 'Una línea tiene disponibilidad de ' + A + ' %, rendimiento de ' + Rn + ' % y calidad de ' + Q + ' %. ¿Cuál es su OEE?', op: ops(P(o), [P((A + Rn + Q) / 3), P(Math.min(A, Rn, Q)), P(A * Rn / 100)], [P(o - 5), P(o + 5)]), r: f(A / 100, 2) + ' × ' + f(Rn / 100, 2) + ' × ' + f(Q / 100, 2) + ' = ' + P(o) + '.' }; }
      const c = pick(rnd, [4, 5, 6, 8, 10, 12]), p = pick(rnd, [55, 60, 65, 70, 72, 75, 78, 80, 85]), G = Math.round(p / 100 * 28800 / c), o = G * c / 288;
      return { q: 'En un turno planeado de 480 min, una estación con tiempo de ciclo ideal de ' + c + ' s entregó ' + G + ' piezas buenas. ¿Cuál es su OEE?', op: ops(P(o), [P(G * c / 480), P(28800 / c / G * 100), P(100 - o)], [P(G * c / 240), P(o - 8)]), r: 'OEE = piezas buenas × ciclo ideal / tiempo planeado = ' + G + ' × ' + c + ' s / 28 800 s = ' + P(o) + ' (es lo mismo que disponibilidad × rendimiento × calidad).' }; },
    m5hz: rnd => { const N = pick(rnd, [900, 1200, 1500, 1750, 1800, 2400, 3000, 3600]), two = rnd() < 0.4, x = two ? 2 : 1, hz = N / 60 * x, Z = v => f(v, 1) + ' Hz';
      return { q: 'Un motor gira a ' + N + ' rpm. ¿A qué frecuencia esperas el pico de vibración por ' + (two ? 'desalineación (2×)' : 'desbalance (1×)') + '?', op: ops(Z(hz), [Z(N * x), Z(N / 60 * (two ? 1 : 2)), Z(N / 3600 * x)], [Z(N * 60 * x), Z(hz + 10)]), r: N + ' rpm / 60 = ' + Z(N / 60) + (two ? '; × 2 = ' + Z(hz) + '.' : ' (1×).') }; },
    m5tendencia: rnd => { const A = pick(rnd, [1.2, 1.5, 1.8, 2, 2.2]), r = pick(rnd, [0.1, 0.15, 0.2, 0.25, 0.3]), W = pick(rnd, [4, 5, 6, 8]), B = Math.round((A + r * W) * 100) / 100, Ls = [4.5, 6, 7.1].filter(x => x > B + 0.4), L = pick(rnd, Ls), w = (L - B) / r, S = x => f(x, 1) + ' semanas';
      return { q: 'La vibración de un motor subió de ' + f(A, 2) + ' a ' + f(B, 2) + ' mm/s en ' + W + ' semanas, de forma pareja. Si el límite de alarma es ' + f(L, 1) + ' mm/s y sigue igual, ¿en cuántas semanas más llegará al límite?', op: ops(S(w), [S(L / r), S((L - A) / r), S((L - B) / (B - A))], [S(w * 2), S(w + W)]), r: 'Sube (' + f(B, 2) + ' − ' + f(A, 2) + ') / ' + W + ' = ' + f(r, 2) + ' mm/s por semana; faltan ' + f(L - B, 2) + ' mm/s; ' + f(L - B, 2) + ' / ' + f(r, 2) + ' = ' + S(w) + '.' }; }
  };
